contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fund);
        require(c.Owner() == address(this));

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 preContractBalance = address(c).balance;
        uint256 preOwnerBalance = address(this).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0 && address(this).balance == preOwnerBalance + preContractBalance);
    }

    receive() external payable {}
}

