// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 fund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        vm.assume(c.Owner() == address(this));
        try c.withdraw() {} catch { return; }
        uint256 preContractBalance = address(c).balance;
        uint256 preOwnerBalance = address(this).balance;
        try c.withdraw() {} catch { return; }
        assertTrue(address(c).balance == 0 && address(this).balance == preOwnerBalance + preContractBalance);
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
